let registration=null,ready=false,waiting=false,checking=false,message='',persistent=null,notify=()=>{};
export const offlineStatus=()=>({ready,waiting,checking,message,persistent});
function update(){ready=!!registration?.active;waiting=!!registration?.waiting;if(waiting)message='Update ready. Your saved players will stay.';else if(registration?.installing)message='Downloading the update…';notify();}
function watch(worker){worker?.addEventListener('statechange',()=>{update();if(worker.state==='redundant'){message='Update could not be downloaded. Try again when online.';notify();}});}
export async function initOffline(onChange){notify=onChange;if(!globalThis.navigator?.serviceWorker)return;try{registration=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});watch(registration.installing);registration.addEventListener('updatefound',()=>{watch(registration.installing);update();});update();await navigator.serviceWorker.ready;update();if(navigator.storage?.persisted){persistent=await navigator.storage.persisted();notify();}}catch{message='Connect to the internet to prepare offline play.';notify();}}
export async function checkForUpdates(){if(!registration){message='Close and reopen this same app while online, then try again.';notify();return;}checking=true;message='Checking for an update…';notify();try{await registration.update();message=registration.waiting?'Update ready. Your saved players will stay.':registration.installing?'Downloading the update…':'No update is ready. Keep this home-screen icon for future updates.';}catch{message='Could not check for updates. Try again when online.';}checking=false;update();}
export async function protectSaves(){try{persistent=navigator.storage?.persist?await navigator.storage.persist():null;message=persistent?'Device storage protection enabled. Keep this icon and a downloaded backup.':'iOS still manages storage automatically. Keep this icon and a downloaded backup.';}catch{message='Storage protection is unavailable. Keep a downloaded player backup.';}notify();}
export function applyOfflineUpdate(){if(!registration?.waiting)return;let reloaded=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reloaded){reloaded=true;location.reload();}});registration.waiting.postMessage({type:'ACTIVATE'});}
